    "guideConcept4Desc": "The Counterfactual Sandbox provides an isolated fork of your database. You can test hypothetical assertions, conflicting rules, or logical triggers in memory. If the hypothetical cascading effects are useful, clicking 'Commit' integrates these changes back into the primary stable database.",
    "guideConcept4Step1": "- Sandbox: Hypothetical RAM-only reasoning inference.",
    "guideConcept4Step2": "- Commit: Permanently write edits to stable SQLite database.",
    "guideConcept4Step3": "- Rollback: Reset the hypothetical sandbox without trace.",
    "guideConcept5Title": "⚖️ 5. Arabic Fuzzy-Modal Logic Engine",
    "guideConcept5Desc": "The Arabic fuzzy logic parser maps natural language qualifiers (e.g. definitely, likely, rarely, maybe) directly to continuous probability metrics, letting the engine auto-calibrate confidence values without manual numeric input (e.g. definitely yields 0.99, rarely yields 0.35).",
    "guideConcept6Title": "🧩 6. Custom Logic Rules Governance",
    "guideConcept6Desc": "LEGEND empowers users to supervise logic rules directly. A dedicated control dashboard allows manual creation, review, and deletion of custom logic rules:",
    "guideConcept6Bullet1": "Manual creation: Input rule name, certainty, antecedents, and consequences using symbolic variables such as ?x and ?y.",
    "guideConcept6Bullet2": "Induction extraction: Trigger the system to scan active database triples and auto-induct latent logic rules.",
    "guideConcept6Bullet3": "Deletion: Instantly delete contradictory or obsolete rules to keep the logical structure pure.",
    "guideConcept6FormulaTitle": "Symbolic Rule Syntax:",
    "guideConcept6FormulaAntecedents": "Antecedents: ?x, contributes_to, ?y AND ?y, subject_to, investment_law",
    "guideConcept6FormulaConsequent": "Consequent: ?x, immune_against, direct_seizure",
    "guideConcept7Title": "🧩 7. Cognitive Prompt Engineering Framework",
    "guideConcept7Desc": "Use this standard system prompt template to structure any logical puzzle or text query into a formatted JSON procedural chain that the LEGEND system can run and solve.",
