    "fedLogsTitle": "📡 سجلات تزامن بروتوكول P2P الفيدرالي",
    "guideMainTitle": "الدليل الإرشادي التفاعلي الكامل لمشروع LEGEND Neuro-Symbolic AI",
    "guideMainDesc": "أهلاً بك في الدليل المعرفي الشامل لـ LEGEND. يهدف هذا المستند لشرح النظريات، والهياكل الرياضية، والبرمجية التي تدير عمليات التفكير والتعلم التراكمي العصبي الرمزي الخالي تماماً من الهلوسة.",
    "guideConcept1Title": "🧠 1. الذكاء الاصطناعي الرمزي العصبي الهجين (Neuro-Symbolic AI)",
    "guideConcept1Desc": "تعد نماذج اللغة الكبيرة (LLMs) ممتازة في فهم وتوليد النصوص اللغوية (البعد العصبي العاطفي)، ولكنها تعاني من الهلوسة وتفتقر للمنطق الدقيق. يعمل نظام LEGEND على حل هذه المشكلة بدمج مستودع منطقي رمزي صلب (SQLite Ontology) مع النماذج اللغوية. تقوم الـ LLM بالتقاط وبثق المفاهيم والعلاقات الدلالية من الجملة وتخزينها كرموز دقيقة في SQLite، بينما يقوم محرك SQLite الصلب بإجراء الاستدلال والاستعلام دون هلوسة بنسبة 100%.",
    "guideConcept1Diagram1": "العقل اللغوي العصبي (LLM Parser)",
    "guideConcept1Diagram2": "(بثق المفاهيم)",
    "guideConcept1Diagram3": "الذاكرة الرمزية الصلبة (SQLite Graph)",
    "guideConcept2Title": "⚖️ 2. المنطق الموزع بالاحتمال (Probabilistic Logic Networks - PLN)",
    "guideConcept2Desc": "على خلاف المنطق الكلاسيكي البولياني الثنائي (صواب/خطأ)، يعبر LEGEND عن كل حقيقة منطقية من خلال درجة اليقين أو الثقة (Confidence) تتراوح بين 0.00 و1.00. تنتقل مستويات اليقين عبر الشبكة الدلالية باستخدام سلاسل التعدي والاحتمالات المتداخلة، مما يمنح النظام القدرة على بناء منطق مرن ومحاكاة العقل البشري في رصد التناقضات ومحاكمة المعارف المعقدة.",
    "guideConcept2Example1": "العلاقة: (أحمد ➔ صديق ➔ محمد) | الثقة = 0.95",
    "guideConcept2Example2": "العلاقة: (محمد ➔ صديق ➔ خالد) | الثقة = 0.90",
    "guideConcept2Example3": "استدلال PLN: (أحمد ➔ صديق ➔ خالد) | الثقة المستنتجة = 0.85",
    "guideConcept3Title": "💤 3. دورة النوم وتقليم المعارف واستنبات الأسئلة (Curiosity & Sleep Cycle)",
    "guideConcept3Desc": "في نهاية العمليات الحيوية، يتعرض العقل لتراكم الضوضاء المعرفية. هنا يأتي دور دورة النوم الإدراكية (Sleep Cycle). يقوم العقل بترتيب الحقائق وفق مركزية الشبكة دلالياً (Graph Centrality)، وإتلاف المعارف غير المترابطة أو ذات الثقة المتدهورة كلياً (Pruning). يتلو ذلك توليد أسئلة الفضول (Curiosity Engine) استناداً إلى الكيانات مجهولة الهوية لتشجيع التعلم النشط وبدء التقصي.",
    "guideConcept3Step1": "1. ترتيب الكيانات بـ Eigenvector Centrality",
    "guideConcept3Step2": "2. التخلص من الحقائق ذات الثقة < 0.40 (التقليم)",
    "guideConcept3Step3": "3. تجميع الكيانات مجهولة الخصائص وصياغة أسئلة تقصي",
    "guideConcept4Title": "🪐 4. فضاء العوالم البديلة (Hypothetical Sandbox Environment)",
    "guideConcept4Desc": "يمكّنك فضاء العوالم البديلة من تشغيل بيئة معزولة (Sandbox) كلياً عن قاعدة المعرفة الأساسية. في هذا الفضاء، تستطيع تجربة الفرضيات المجنونة وغير الواقعية واستنباط نتائجها المتسلسلة دون التأثير على ذاكرتك الثابتة. إذا ثبت صحة فرضيات العالم البديل وجدواها المعرفية، يمكنك الضغط على زر تثبيت ودمج لترحيلها فوراً وتكاملها مع شبكة الحقائق العامة.",
    "guideConcept4Step1": "- فضاء بديل: استنتاجات مؤقتة بالـ RAM والذاكرة التخيلية.",
    "guideConcept4Step2": "- تثبيت (Commit): دمج حقيقي مع SQLite.",
    "guideConcept4Step3": "- تراجع (Rollback): مسح العالم الافتراضي والرجوع للحالة الصفرية.",
    "guideConcept5Title": "⚖️ 5. المنطق الموجه والمضبب العربي (Arabic Fuzzy-Modal Logic Engine)",
    "guideConcept5Desc": "يتيح محرك المنطق الموجه والمضبب إدراك الفروقات اللغوية الدقيقة في التعبيرات العربية. فعند استخدام كلمات مثل غالباً، نادراً، تماماً، بالتأكيد، واحتمال، يفهم محرك LEGEND الطبيعة المضببة للجملة ويقوم بتعديل مؤشر الثقة واليقين تلقائياً (مثال: نادراً تعطي ثقة 0.35، وبالتأكيد تمنح 0.99).",
    "guideConcept6Title": "🧩 6. حوكمة وإدارة القواعد المنطقية المخصصة (Rules Governance)",
    "guideConcept6Desc": "الآن يمكنك حوكمة القواعد الرمزية يدوياً! يوفر LEGEND واجهة ديناميكية لإضافة، وتعديل، وحذف القواعد المنطقية التي توجه تفكير النظام:",
    "guideConcept6Bullet1": "إضافة قاعدة يدوية: حدد اسم القاعدة، معامل اليقين، شروط القاعدة (Antecedents)، والنتيجة (Consequent) باستخدام صيغ المتغيرات الرمزية مثل ?x و ?y.",
    "guideConcept6Bullet2": "حث واستخلاص: يقوم النظام بالتنقيب في قاعدة المعرفة للعثور على علاقات متكررة واستنباط القواعد تلقائياً بنظام الـ Machine Induction.",
    "guideConcept6Bullet3": "حذف قاعدة: بنقرة واحدة، يمكنك التخلص من أي قاعدة خاطئة أو غير ضرورية لضمان نقاء البنية الاستدلالية وموثوقيتها المطلقة.",
    "guideConcept6FormulaTitle": "الصيغة الرمزية للقاعدة:",
    "guideConcept6FormulaAntecedents": "الشروط: ?x, مساهم_في, ?y و ?y, تخضع_لـ, قانون_الاستثمار",
    "guideConcept6FormulaConsequent": "النتيجة: ?x, له_حصانة_ضد, الحجز_المباشر",
    "guideConcept7Title": "🧩 7. تلقينة مهندس الإجراءات المعرفية المتسلسلة (Cognitive Prompt Engineering)",
    "guideConcept7Desc": "تُستخدم هذه التلقينة لتحويل أي لغز منطقي أو مسألة فكرية إلى سلسلة إجراءات معرفية متكاملة. يقوم الذكاء الاصطناعي بتفكيك الحل إلى خطوات متتالية وتنسيقها على شكل طلب برمجياً لرفعها فوراً في واجهة الاستدلال بالتطبيق.",
    "guideCopyPromptBtn": "نسخ التلقينة الموحدة",
    "promptCopySuccess": "📋 تم نسخ تلقينة الألغاز المنطقية الموحدة إلى الحافظة بنجاح!",
