    "modalWsModeActiveDesc": "يحلم، يستنتج تلقائياً، ويبحث عن فجوات الفضول",
    "modalWsModeStrictTitle": "🔒 وضع الحقائق الثابتة",
    "modalWsModeStrictDesc": "يلتزم بمدخلاتك 100%، ويكتشف التعارضات المنطقية فقط",
    "modalWsCancelBtn": "إلغاء",
