    "metaWaitingForAssessment": "Cliquez sur 'Actualiser le diagnostic' pour scanner le graphe.",
    "cognitivePrompt": "Vous êtes un architecte cognitif neuro-symbolique. Votre tâche consiste à recevoir un puzzle logique, un dilemme ou un problème de raisonnement, puis à le déconstruire pour générer une « procédure cognitive séquentielle » qui représente l'algorithme de raisonnement humain et symbolique nécessaire pour résoudre ce problème avec une précision absolue et de manière organisée.\n\nVous devez analyser le puzzle et formuler des étapes logiques, où chaque étape mène logiquement et progressivement à la suivante, en évitant les généralités et en vous concentrant sur les règles de déduction, le raisonnement inversé et le filtrage éliminatoire.\n\nFormatez la sortie finale strictement sous la forme d'un JSON propre correspondant exactement à la structure suivante, sans aucune introduction ou formatage markdown supplémentaire :\n\n{\n  \"procedure_name\": \"nom_de_la_procedure_cognitive\",\n  \"steps\": [\n    \"Première étape : ...\",\n    \"Deuxième étape : ...\",\n    \"Troisième étape : ...\"\n  ]\n}\n\nAvertissement : Renvoyez UNIQUEMENT le code JSON, sans aucun texte d'introduction, explication ou balise markdown.",
    "guideMainTitle": "Guide Interactif Complet de LEGEND Neuro-Symbolic AI",
    "guideMainDesc": "Bienvenue dans le guide de connaissances LEGEND. Ce document présente en détail les théories, les modèles mathématiques et les structures d'implémentation qui soutiennent l'intégration connexionniste-symbolique.",
    "guideConcept1Title": "🧠 1. IA Neuro-Symbolique Hybride",
    "guideConcept1Desc": "Les grands modèles de langage (LLM) excellent dans l'analyse du langage naturel mais souffrent d'hallucinations. LEGEND résout ce problème en couplant les architectures connexionnistes à une base de données d'ontologie SQLite symbolique stricte. Le LLM extrait les tuples sémantiques des entrées humaines, tandis que le moteur rigide évalue les contraintes logiques et répond aux requêtes avec 0 % d'hallucinations.",
    "guideConcept1Diagram1": "Cerveau Connexionniste (Analyseur LLM)",
    "guideConcept1Diagram2": "(Extraction de Concepts)",
    "guideConcept1Diagram3": "Mémoire Symbolique Stricte (Graphe SQLite)",
    "guideConcept2Title": "⚖️ 2. Réseaux Logiques Probabilistes (PLN)",
    "guideConcept2Desc": "Contrairement à la logique booléenne classique (vrai/faux), LEGEND quantifie les faits à l'aide d'un paramètre de confiance continu entre 0.00 et 1.00. Les valeurs de confiance se propagent à travers le graphe sémantique via des chaînes transitives, permettant au réseau d'émuler le raisonnement humain flou et de détecter les paradoxes cognitifs.",
    "guideConcept2Example1": "Fait: (Ahmad ➔ ami ➔ Mohammad) | Confiance = 0.95",
    "guideConcept2Example2": "Fait: (Mohammad ➔ ami ➔ Khalid) | Confiance = 0.90",
    "guideConcept2Example3": "Inférence PLN: (Ahmad ➔ ami ➔ Khalid) | Confiance Inférée = 0.85",
    "guideConcept3Title": "💤 3. Curiosité & Cycle de Sommeil Cognitif",
    "guideConcept3Desc": "Pour lutter contre l'entropie sémantique cumulative, le système exécute périodiquement un cycle de sommeil cognitif. Le moteur classe les nœuds de concept en utilisant la centralité de vecteur propre du graphe, élague les liens faibles avec une confiance < 0.40, et déploie le moteur de curiosité pour formuler des questions d'investigation sur les entités sous-définies.",
    "guideConcept3Step1": "1. Classer les nœuds à l'aide de la centralité de vecteur propre du graphe",
    "guideConcept3Step2": "2. Élaguer les faits avec une confiance < 0.40",
    "guideConcept3Step3": "3. Agréger les entités vagues pour formuler des requêtes de curiosité",
    "guideConcept4Title": "🪐 4. Bac à Sable Contrefactuel Hypothetique",
    "guideConcept4Desc": "Le bac à sable contrefactuel fournit un embranchement isolé de votre base de données. Vous pouvez tester des affirmations hypothétiques, des règles contradictoires ou des déclencheurs logiques en mémoire. Si les effets en cascade hypothétiques sont utiles, cliquer sur 'Valider' intègre ces modifications dans la base de données stable principale.",
    "guideConcept4Step1": "- Bac à sable: Inférence de raisonnement hypothétique isolée en RAM.",
    "guideConcept4Step2": "- Valider: Écrire définitivement les modifications dans la base SQLite stable.",
    "guideConcept4Step3": "- Annuler: Réinitialiser le bac à sable hypothétique sans laisser de trace.",
    "guideConcept5Title": "⚖️ 5. Moteur de Logique Floue-Modale Arabe",
    "guideConcept5Desc": "L'analyseur de logique floue arabe mappe les qualificateurs de langage naturel (ex. certainement, probablement, rarement, peut-être) directement sur des métriques de probabilité continues, permettant au moteur de calibrer automatiquement les valeurs de confiance sans saisie numérique manuelle (ex. 'certainement' donne 0.99, 'rarement' donne 0.35).",
    "guideConcept6Title": "🧩 6. Gouvernance des Règles Logiques Personnalisées",
    "guideConcept6Desc": "LEGEND permet aux utilisateurs de superviser directement les règles logiques. Un panneau de contrôle dédié permet la création manuelle, la révision et la suppression de règles logiques personnalisées:",
    "guideConcept6Bullet1": "Création manuelle: Saisissez le nom de la règle, la certitude, les antécédents et les conséquences en utilisant des variables symboliques telles que ?x et ?y.",
    "guideConcept6Bullet2": "Extraction par induction: Déclenchez le système pour analyser les triplets actifs de la base de données et auto-induire des règles logiques latentes.",
    "guideConcept6Bullet3": "Suppression: Supprimez instantanément les règles contradictoires ou obsolètes pour garder la structure logique pure.",
    "guideConcept6FormulaTitle": "Syntaxe de Règle Symbolique:",
    "guideConcept6FormulaAntecedents": "Antécédents: ?x, contribue_a, ?y ET ?y, sujet_a, loi_investissement",
    "guideConcept6FormulaConsequent": "Conséquent: ?x, immune_contre, saisie_directe",
    "guideConcept7Title": "🧩 7. Cadre d'Ingénierie de Prompt Cognitif",
    "guideConcept7Desc": "Utilisez ce modèle de prompt système standard pour structurer tout puzzle logique ou requête textuelle en une chaîne procédurale JSON formatée que le système LEGEND peut exécuter et résoudre.",
