    "metaVagueLinks": "enlaces",
    "metaVagueConfidence": "confianza",
    "metaWaitingForAssessment": "Haga clic en 'Actualizar diagnóstico' para escanear el gráfico.",
    "cognitivePrompt": "Eres un arquitecto cognitivo neurosimbólico. Tu tarea es recibir cualquier acertijo lógico, dilema o problema de razonamiento y luego deconstruirlo para generar un \"Procedimiento cognitivo secuencial\" que represente el algoritmo de razonamiento simbólico y humano necesario para resolver este problema con absoluta precisión y de manera organizada.\n\nDebes analizar el acertijo y formular pasos lógicos, donde cada paso conduzca de manera lógica y progresiva al siguiente, evitando generalidades y centrándote en las reglas de deducción, el razonamiento hacia atrás y el filtrado eliminatorio.\n\nFormatea la salida final estrictamente como un JSON limpio que coincida exactamente con la siguiente estructura, sin introducciones ni formatos markdown adicionales:\n\n{\n  \"procedure_name\": \"nombre_del_procedimiento_cognitivo\",\n  \"steps\": [\n    \"Primer paso: ...\",\n    \"Segundo paso: ...\",\n    \"Tercer paso: ...\"\n  ]\n}\n\nAdvertencia: Devuelve ÚNICAMENTE el código JSON, sin ningún texto de introducción, explicación ni etiquetas markdown.",
    "guideMainTitle": "Guía Interactiva Completa de LEGEND Neuro-Symbolic AI",
    "guideMainDesc": "Bienvenido a la guía de conocimiento de LEGEND. Este documento detalla las teorías, los modelos matemáticos y las estructuras de implementación que impulsan la integración conexionista-simbólica.",
    "guideConcept1Title": "🧠 1. IA Neuro-Simbólica Híbrida",
    "guideConcept1Desc": "Los modelos de lenguaje grande (LLM) sobresalen en el análisis del lenguaje natural pero sufren alucinaciones. LEGEND resuelve esto al acoplar arquitecturas conexionistas con una base de datos de ontología SQLite simbólica estricta. El LLM extrae tuplas semánticas de las entradas humanas, mientras que el motor rígido evalúa las restricciones lógicas y resuelve las consultas con un 0% de alucinaciones.",
    "guideConcept1Diagram1": "Cerebro Conexionista (Analizador LLM)",
    "guideConcept1Diagram2": "(Extracción de Conceptos)",
    "guideConcept1Diagram3": "Memoria Simbólica Estricta (Gráfico SQLite)",
    "guideConcept2Title": "⚖️ 2. Redes Lógicas Probabilísticas (PLN)",
    "guideConcept2Desc": "A diferencia de la lógica booleana clásica (verdadero/falso), LEGEND cuantifica los hechos utilizando un parámetro de confianza continuo entre 0.00 y 1.00. Los valores de confianza se propagan a través del gráfico semántico a través de cadenas transitivas, lo que permite a la red emular el razonamiento humano difuso y detectar paradojas cognitivas.",
    "guideConcept2Example1": "Hecho: (Ahmad ➔ amigo ➔ Mohammad) | Confianza = 0.95",
    "guideConcept2Example2": "Hecho: (Mohammad ➔ amigo ➔ Khalid) | Confianza = 0.90",
    "guideConcept2Example3": "Inferencia PLN: (Ahmad ➔ amigo ➔ Khalid) | Confianza Inferida = 0.85",
    "guideConcept3Title": "💤 3. Curiosidad y Ciclo de Sueño Cognitivo",
    "guideConcept3Desc": "Para combatir la entropía semántica acumulativa, el sistema ejecuta periódicamente un Ciclo de Sueño Cognitivo. El motor clasifica los nodos de concepto mediante la centralidad del vector propio del gráfico, poda los enlaces débiles con confianza < 0.40 y despliega el motor de curiosidad para formular preguntas de investigación sobre entidades poco definidas.",
    "guideConcept3Step1": "1. Clasificar nodos utilizando la centralidad del vector propio del gráfico",
    "guideConcept3Step2": "2. Podar hechos con confianza < 0.40",
    "guideConcept3Step3": "3. Agregar entidades vagas para formular consultas de curiosidad",
    "guideConcept4Title": "🪐 4. Caja de Arena Contrafactual Hipotética",
    "guideConcept4Desc": "La caja de arena contrafactual proporciona una bifurcación aislada de su base de datos. Puede probar afirmaciones hipotéticas, reglas en conflicto o disparadores lógicos en la memoria. Si los efectos en cascada hipotéticos son útiles, al hacer clic en 'Confirmar' se integran estos cambios nuevamente en la base de datos estable principal.",
    "guideConcept4Step1": "- Caja de arena: Inferencia de razonamiento hipotético aislada en RAM.",
    "guideConcept4Step2": "- Confirmar: Escribir modificaciones permanentemente en la base de datos SQLite estable.",
    "guideConcept4Step3": "- Revertir: Restablecer la caja de arena hipotética sin dejar rastro.",
    "guideConcept5Title": "⚖️ 5. Motor de Lógica Difuso-Modal Árabe",
    "guideConcept5Desc": "El analizador de lógica difusa árabe mapea los calificadores del lenguaje natural (por ejemplo, definitivamente, probablemente, raramente, tal vez) directamente a métricas de probabilidad continuas, lo que permite al motor autocalibrar los valores de confianza sin entrada numérica manual (por ejemplo, definitivamente produce 0.99, raramente produce 0.35).",
    "guideConcept6Title": "🧩 6. Gobernanza de Reglas Lógicas Personalizadas",
    "guideConcept6Desc": "LEGEND permite a los usuarios supervisar las reglas lógicas directamente. Un panel de control dedicado permite la creación manual, revisión y eliminación de reglas lógicas personalizadas:",
    "guideConcept6Bullet1": "Creación manual: Ingrese el nombre de la regla, certeza, antecedentes y consecuencias utilizando variables simbólicas como ?x y ?y.",
    "guideConcept6Bullet2": "Extracción por inducción: Active el sistema para escanear triples de la base de datos activa e inducir automáticamente reglas lógicas latentes.",
    "guideConcept6Bullet3": "Eliminación: Elimine instantáneamente reglas contradictorias u obsoletas para mantener pura la estructura lógica.",
    "guideConcept6FormulaTitle": "Sintaxis de Regla Simbólica:",
    "guideConcept6FormulaAntecedents": "Antecedentes: ?x, contribuye_a, ?y Y ?y, sujeto_a, ley_inversion",
    "guideConcept6FormulaConsequent": "Consecuente: ?x, inmune_contra, embargo_directo",
    "guideConcept7Title": "🧩 7. Marco de Ingeniería de Prompts Cognitivos",
    "guideConcept7Desc": "Utilice esta plantilla de prompt del sistema estándar para estructurar cualquier acertijo lógico o consulta de texto en una cadena de procedimiento JSON formateada que el sistema LEGEND pueda ejecutar y resolver.",
