    "cognitivePrompt": "你是一个神经符号认知架构师。你的任务是接收任何逻辑谜题、两难困境或推理问题，然后解构它以生成一个“顺序认知过程”，该过程代表解决这个问题所需的绝对精确且有条理的人类和符号推理算法。\n\n你必须分析谜题并制定逻辑步骤，其中每一步都逻辑地、渐进地引向下一步，避免笼统，并专注于演绎规则、逆向推理和排除性过滤。\n\n将最终输出严格格式化为符合以下结构的干净 JSON，不包含任何介绍或附加的 markdown 格式：\n\n{\n  \"procedure_name\": \"认知过程名称\",\n  \"steps\": [\n    \"第一步: ...\",\n    \"第二步: ...\",\n    \"第三步: ...\"\n  ]\n}\n\n警告：仅返回 JSON 代码，绝对不要包含任何介绍性文本、解释或 markdown 标记。",
    "guideMainTitle": "LEGEND 神经符号 AI 综合交互指南",
    "guideMainDesc": "欢迎阅读 LEGEND 知识指南。本文件详细介绍了支持连接主义与符号主义融合的理论、数学模型和实现结构。",
    "guideConcept1Title": "🧠 1. 混合神经符号 AI",
    "guideConcept1Desc": "大语言模型（LLMs）擅长自然语言解析，但存在幻觉问题。LEGEND 通过将连接主义架构与严格的符号化 SQLite 本体数据库相结合来解决这一问题。LLM 从人类输入中提取语义元组，而严格的引擎则评估逻辑约束并以 0% 的幻觉率解答查询。",
    "guideConcept1Diagram1": "连接主义大脑 (LLM 解析器)",
    "guideConcept1Diagram2": "(概念提取)",
    "guideConcept1Diagram3": "严格符号记忆 (SQLite 图)",
    "guideConcept2Title": "⚖️ 2. 概率逻辑网络 (PLN)",
    "guideConcept2Desc": "与传统的布尔逻辑（真/假）不同，LEGEND 使用 0.00 到 1.00 之间的连续置信度参数来量化事实。置信度值通过传递链在语义图中传播，使网络能够模拟模糊的人类推理并检测认知悖论。",
    "guideConcept2Example1": "事实: (Ahmad ➔ friend ➔ Mohammad) | 置信度 = 0.95",
    "guideConcept2Example2": "事实: (Mohammad ➔ friend ➔ Khalid) | 置信度 = 0.90",
    "guideConcept2Example3": "PLN 推理: (Ahmad ➔ friend ➔ Khalid) | 推理置信度 = 0.85",
    "guideConcept3Title": "💤 3. 好奇心与认知睡眠周期",
    "guideConcept3Desc": "为了对抗累积的语义熵，系统定期执行认知睡眠周期。引擎使用特征向量图中心性对概念节点进行排序，修剪置信度 < 0.40 的微弱链接，并部署好奇心引擎对定义不足的实体提出调查性问题。",
    "guideConcept3Step1": "1. 使用特征向量图中心性对节点进行排序",
    "guideConcept3Step2": "2. 修剪置信度 < 0.40 的事实",
    "guideConcept3Step3": "3. 聚合模糊实体以构建好奇心查询",
    "guideConcept4Title": "🪐 4. 假设性反事实沙盒",
    "guideConcept4Desc": "反事实沙盒提供了数据库的隔离分叉。您可以在内存中测试假设性的断言、冲突的规则或逻辑触发器。如果假设的级联效应有用，点击“提交”可将这些更改集成回主稳定数据库。",
    "guideConcept4Step1": "- 沙盒: 内存中隔离的假设性推理推理。",
    "guideConcept4Step2": "- 提交: 将修改永久写入稳定的 SQLite 数据库。",
    "guideConcept4Step3": "- 回滚: 重置假设性沙盒而不留痕迹。",
    "guideConcept5Title": "⚖️ 5. 阿拉伯语模糊模态逻辑引擎",
    "guideConcept5Desc": "阿拉伯语模糊逻辑解析器将自然语言限定词（例如：绝对、可能、很少、也许）直接映射到连续的概率度量，使引擎能够在无需手动数值输入的情况下自动校准置信度值（例如，绝对产生 0.99，很少产生 0.35）。",
    "guideConcept6Title": "🧩 6. 自定义逻辑规则治理",
    "guideConcept6Desc": "LEGEND 赋予用户直接监督逻辑规则的权力。专用的控制面板允许手动创建、审查和删除自定义逻辑规则:",
    "guideConcept6Bullet1": "手动创建：使用诸如 ?x 和 ?y 等符号变量输入规则名称、确定性、前件和后件。",
    "guideConcept6Bullet2": "归纳提取：触发系统扫描活跃的数据库三元组并自动归纳潜在的逻辑规则。",
    "guideConcept6Bullet3": "删除：立即删除冲突或过时的规则，以保持逻辑结构的纯洁。",
    "guideConcept6FormulaTitle": "符号规则语法:",
    "guideConcept6FormulaAntecedents": "前件: ?x, contributes_to, ?y AND ?y, subject_to, investment_law",
    "guideConcept6FormulaConsequent": "后件: ?x, immune_against, direct_seizure",
    "guideConcept7Title": "🧩 7. 认知提示工程框架",
    "guideConcept7Desc": "使用此标准系统提示模板将任何逻辑谜题或文本查询结构化为格式化的 JSON 程序链，LEGEND 系统可以运行并解决该程序链。",
    "guideCopyPromptBtn": "复制系统提示",
