    "metaNoVagueConcepts": "Tüm kavramlar yeterli ilişkisel bağlama ve dengeli güven metriklerine sahiptir.",
    "metaVagueLinks": "bağlantı",
    "metaVagueConfidence": "güven",
    "metaWaitingForAssessment": "Teşhis grafiğini taramak için 'Teşhisi Yenile' düğmesine tıklayın.",
    "cognitivePrompt": "Nöro-Sembolik Bilişsel Mimarsınız. Göreviniz herhangi bir mantık bulmacasını, ikilemi veya muhakeme problemini almak ve ardından bu problemi mutlak hassasiyetle ve düzenli bir şekilde çözmek için gereken insan ve sembolik muhakeme algoritmasını temsil eden bir \"Sıralı Bilişsel Prosedür\" oluşturmak üzere onu parçalarına ayırmaktır.\n\nBulmacayı analiz etmeli ve her adımın mantıklı ve aşamalı olarak bir sonrakine yol açtığı, genellemelerden kaçındığı ve çıkarım kurallarına, geriye doğru muhakemeye ve eleyici filtrelemeye odaklandığı mantıksal adımlar formüle etmelisiniz.\n\nNihai çıktıyı, ek bir giriş veya markdown biçimlendirmesi olmaksızın, aşağıdaki yapıya tam olarak uyan temiz bir JSON olarak biçimlendirin:\n\n{\n  \"procedure_name\": \"bilgisel_surec_adi\",\n  \"steps\": [\n    \"İlk adım: ...\",\n    \"İkinci adım: ...\",\n    \"Üçüncü adım: ...\"\n  ]\n}\n\nUyarı: YALNIZCA JSON kodunu döndürün, hiçbir tanıtım metni, açıklama veya markdown etiketi içermemelidir.",
    "guideMainTitle": "LEGEND Nöro-Sembolik Yapay Zeka Kapsamlı Etkileşimli Kılavuz",
    "guideMainDesc": "LEGEND Bilgi Kılavuzuna hoş geldiniz. Bu belge, bağlantısal-sembolik entegrasyonu güçlendiren teorileri, matematiksel modelleri ve uygulama yapılarını ayrıntılı olarak açıklamaktadır.",
    "guideConcept1Title": "🧠 1. Hibrit Nöro-Sembolik Yapay Zeka",
    "guideConcept1Desc": "Büyük Dil Modelleri (LLM'ler) doğal dil analizinde mükemmeldir ancak halüsinasyonlardan muzdariptir. LEGEND, bağlantısal mimarileri katı bir sembolik SQLite ontoloji veritabanıyla eşleştirerek bunu çözer. LLM, insan girdilerinden anlamsal demetleri çıkarırken, katı motor mantıksal kısıtlamaları değerlendirir ve sorguları %0 halüsinasyonla çözer.",
    "guideConcept1Diagram1": "Bağlantısal Beyin (LLM Çözümleyici)",
    "guideConcept1Diagram2": "(Kavram Çıkarımı)",
    "guideConcept1Diagram3": "Katı Sembolik Bellek (SQLite Grafiği)",
    "guideConcept2Title": "⚖️ 2. Olasılıksal Mantık Ağları (PLN)",
    "guideConcept2Desc": "Klasik boole mantığının aksine (doğru/yanlış), LEGEND gerçekleri 0.00 ile 1.00 arasında sürekli bir güven parametresi kullanarak nicelleştirir. Güven değerleri, geçişli zincirler yoluyla anlamsal grafik boyunca yayılır, bu da ağın bulanık insan muhakemesini taklit etmesine ve bilişsel paradoksları tespit etmesine olanak tanır.",
    "guideConcept2Example1": "Gerçek: (Ahmad ➔ arkadaş ➔ Mohammad) | Güven = 0.95",
    "guideConcept2Example2": "Gerçek: (Mohammad ➔ arkadaş ➔ Khalid) | Güven = 0.90",
    "guideConcept2Example3": "PLN Çıkarımı: (Ahmad ➔ arkadaş ➔ Khalid) | Çıkarılan Güven = 0.85",
    "guideConcept3Title": "💤 3. Merak & Bilişsel Uyku Döngüsü",
    "guideConcept3Desc": "Kümülatif anlamsal entropiyle mücadele etmek için sistem periyodik olarak Bilişsel Uyku Döngüsü yürütür. Motor, grafik özvektör merkeziliğini kullanarak kavram düğümlerini sıralar, güven < 0.40 olan zayıf bağlantıları budar ve yetersiz tanımlanmış varlıklar hakkında araştırma soruları formüle etmek için Merak Motorunu devreye sokar.",
    "guideConcept3Step1": "1. Grafik Özvektör Merkeziliğini Kullanarak Düğümleri Sırala",
    "guideConcept3Step2": "2. Güven < 0.40 olan gerçekleri buda",
    "guideConcept3Step3": "3. Merak sorguları formüle etmek için belirsiz varlıkları topla",
    "guideConcept4Title": "🪐 4. Hipotetik Karşıt Gerçeklik Sandbox'ı",
    "guideConcept4Desc": "Karşıt Gerçeklik Sandbox'ı, veritabanınızın yalıtılmış bir çatalını sağlar. Bellekteki hipotetik iddiaları, çelişen kuralları veya mantıksal tetikleyicileri test edebilirsiniz. Hipotetik basamaklı etkiler yararlıysa, 'Uygula'yı tıklamak bu değişiklikleri birincil kararlı veritabanına geri entegre eder.",
    "guideConcept4Step1": "- Sandbox: Bellekte yalıtılmış hipotetik çıkarım muhakemesi.",
    "guideConcept4Step2": "- Uygula: Değişiklikleri kararlı SQLite veritabanına kalıcı olarak yaz.",
    "guideConcept4Step3": "- Geri Al: Hipotetik sandbox'ı iz bırakmadan sıfırla.",
    "guideConcept5Title": "⚖️ 5. Arapça Bulanık-Kiplik Mantık Motoru",
    "guideConcept5Desc": "Arapça bulanık mantık çözümleyici, doğal dil niteleyicilerini (örneğin kesinlikle, muhtemelen, nadiren, belki) doğrudan sürekli olasılık metriklerine eşler ve motorun manuel sayısal girdi olmadan güven değerlerini otomatik olarak kalibre etmesini sağlar (örneğin kesinlikle 0.99, nadiren 0.35 üretir).",
    "guideConcept6Title": "🧩 6. Özel Mantık Kuralları Yönetimi",
    "guideConcept6Desc": "LEGEND, kullanıcılara mantık kurallarını doğrudan denetleme yetkisi verir. Özel bir kontrol paneli, özel mantık kurallarının manuel olarak oluşturulmasına, incelenmesine ve silinmesine olanak tanır:",
    "guideConcept6Bullet1": "Manuel oluşturma: ?x ve ?y gibi sembolik değişkenleri kullanarak kural adını, kesinliğini, öncüllerini ve sonuçlarını girin.",
    "guideConcept6Bullet2": "Tümevarım çıkarımı: Aktif veritabanı üçlülerini taramak ve gizli mantık kurallarını otomatik olarak türetmek için sistemi tetikleyin.",
    "guideConcept6Bullet3": "Silme: Mantıksal yapıyı saf tutmak için çelişkili veya eski kuralları anında silin.",
    "guideConcept6FormulaTitle": "Sembolik Kural Sözdizimi:",
    "guideConcept6FormulaAntecedents": "Öncüller: ?x, katkida_bulunur, ?y VE ?y, tabidir, yatirim_yasasi",
    "guideConcept6FormulaConsequent": "Sonuç: ?x, muaftir, dogrudan_el_koyma",
    "guideConcept7Title": "🧩 7. Bilişsel Prompt Mühendisliği Çerçevesi",
    "guideConcept7Desc": "Herhangi bir mantık bulmacasını veya metin sorgusunu, LEGEND sisteminin çalıştırıp çözebileceği biçimlendirilmiş bir JSON yordamsal zincirine yapılandırmak için bu standart sistem promptu şablonunu kullanın.",
