    "metaVagueConceptsTitle": "⚖️ Vage Konzepte (Geringer Grad oder geringes Vertrauen)",
    "metaNoVagueConcepts": "Alle Konzepte haben ausreichend relationalen Kontext und ausgewogene Vertrauensmetriken.",
    "metaVagueLinks": "Verknüpfungen",
    "metaVagueConfidence": "Vertrauen",
    "metaWaitingForAssessment": "Klicken Sie auf 'Diagnose aktualisieren', um den Begriffsgraphen zu scannen.",
    "cognitivePrompt": "Sie sind ein neuro-symbolischer kognitiver Architekt. Ihre Aufgabe ist es, logische Rätsel, Dilemmata oder Argumentationsprobleme zu empfangen und sie dann zu dekonstruieren, um eine \"Sequenzielle kognitive Prozedur\" zu generieren, die den Algorithmus für menschliches und symbolisches Denken darstellt, der erforderlich ist, um dieses Problem mit absoluter Präzision und in einer organisierten Weise zu lösen.\n\nSie müssen das Rätsel analysieren und logische Schritte formulieren, wobei jeder Schritt logisch und fortschreitend zum nächsten führt, Allgemeinplätze vermeidet und sich auf Deduktionsregeln, Rückwärtsdenken und eliminierende Filterung konzentriert.\n\nFormatieren Sie die endgültige Ausgabe streng als sauberes JSON, das genau der folgenden Struktur entspricht, ohne Einleitungen oder zusätzliche Markdown-Formatierungen:\n\n{\n  \"procedure_name\": \"Name_der_kognitiven_Prozedur\",\n  \"steps\": [\n    \"Erster Schritt: ...\",\n    \"Zweiter Schritt: ...\",\n    \"Dritter Schritt: ...\"\n  ]\n}\n\nWarnung: Geben Sie NUR den JSON-Code zurück, absolut ohne Einleitungstext, Erklärungen oder Markdown-Tags.",
    "guideMainTitle": "Umfassender interaktiver Leitfaden zur LEGEND Neuro-Symbolischen KI",
    "guideMainDesc": "Willkommen beim LEGEND Wissensleitfaden. Dieses Dokument beschreibt die Theorien, mathematischen Modelle und Implementierungsstrukturen, die die konnektionistisch-symbolische Integration ermöglichen.",
    "guideConcept1Title": "🧠 1. Hybride Neuro-Symbolische KI",
    "guideConcept1Desc": "Große Sprachmodelle (LLMs) sind hervorragend in der Analyse natürlicher Sprache, leiden jedoch unter Halluzinationen. LEGEND löst dies durch die Kopplung konnektionistischer Architekturen mit einer starren symbolischen SQLite-Ontologiedatenbank. Das LLM extrahiert semantische Tupel aus menschlichen Eingaben, während die starre Engine logische Einschränkungen bewertet und Abfragen mit 0 % Halluzinationen löst.",
    "guideConcept1Diagram1": "Konnektionistisches Gehirn (LLM-Parser)",
    "guideConcept1Diagram2": "(Konzept-Extraktion)",
    "guideConcept1Diagram3": "Starrer symbolischer Speicher (SQLite-Graph)",
    "guideConcept2Title": "⚖️ 2. Probabilistische Logische Netzwerke (PLN)",
    "guideConcept2Desc": "Im Gegensatz zur klassischen booleschen Logik (wahr/falsch) quantifiziert LEGEND Fakten mit einem kontinuierlichen Vertrauensparameter zwischen 0.00 und 1.00. Vertrauenswerte breiten sich über transitive Ketten im semantischen Graphen aus, sodass das Netzwerk unscharfes menschliches Denken emulieren und kognitive Paradoxien erkennen kann.",
    "guideConcept2Example1": "Fakt: (Ahmad ➔ Freund ➔ Mohammad) | Vertrauen = 0.95",
    "guideConcept2Example2": "Fakt: (Mohammad ➔ Freund ➔ Khalid) | Vertrauen = 0.90",
    "guideConcept2Example3": "PLN-Inferenz: (Ahmad ➔ Freund ➔ Khalid) | Abgeleitetes Vertrauen = 0.85",
    "guideConcept3Title": "💤 3. Neugier & Kognitiver Schlafzyklus",
    "guideConcept3Desc": "Um die kumulative semantische Entropie zu bekämpfen, führt das System regelmäßig einen kognitiven Schlafzyklus durch. Die Engine ordnet Konzeptknoten mithilfe der Eigenvektor-Graphzentralität, schneidet schwache Verbindungen mit einem Vertrauen < 0.40 ab und setzt die Neugier-Engine ein, um investigative Fragen zu unterdefinierten Entitäten zu formulieren.",
    "guideConcept3Step1": "1. Ordnen der Knoten mittels Eigenvektor-Graphzentralität",
    "guideConcept3Step2": "2. Entfernen von Fakten mit Vertrauen < 0.40",
    "guideConcept3Step3": "3. Aggregieren vager Entitäten zur Formulierung von Neugier-Abfragen",
    "guideConcept4Title": "🪐 4. Hypothetische kontrafaktische Sandbox",
    "guideConcept4Desc": "Die kontrafaktische Sandbox bietet einen isolierten Fork Ihrer Datenbank. Sie können hypothetische Behauptungen, widersprüchliche Regeln oder logische Auslöser im Speicher testen. Wenn die hypothetischen kaskadierenden Effekte nützlich sind, werden diese Änderungen durch Klicken auf 'Übernehmen' wieder in die primäre stabile Datenbank integriert.",
    "guideConcept4Step1": "- Sandbox: Isolierte hypothetische Inferenz im Arbeitsspeicher.",
    "guideConcept4Step2": "- Übernehmen: Änderungen dauerhaft in die stabile SQLite-Datenbank schreiben.",
    "guideConcept4Step3": "- Verwerfen: Zurücksetzen der hypothetischen Sandbox ohne Spuren.",
    "guideConcept5Title": "⚖️ 5. Arabische Fuzzy-Modale Logik-Engine",
    "guideConcept5Desc": "Der arabische Fuzzy-Logik-Parser bildet natürliche Sprachqualifikatoren (z. B. definitiv, wahrscheinlich, selten, vielleicht) direkt auf kontinuierliche Wahrscheinlichkeitsmetriken ab, sodass die Engine Vertrauenswerte automatisch ohne manuelle numerische Eingabe kalibrieren kann (z. B. ergibt 'definitiv' 0.99, 'selten' ergibt 0.35).",
    "guideConcept6Title": "🧩 6. Verwaltung benutzerdefinierter Logikregeln",
    "guideConcept6Desc": "LEGEND ermöglicht es Benutzern, Logikregeln direkt zu überwachen. Ein dediziertes Kontroll-Dashboard ermöglicht die manuelle Erstellung, Überprüfung und Löschung benutzerdefinierter Logikregeln:",
    "guideConcept6Bullet1": "Manuelle Erstellung: Geben Sie Regelname, Gewissheit, Antezedenzien und Konsequenzen unter Verwendung symbolischer Variablen wie ?x und ?y ein.",
    "guideConcept6Bullet2": "Induktions-Extraktion: Veranlassen Sie das System, aktive Datenbank-Tripel zu scannen und latente Logikregeln automatisch zu induzieren.",
    "guideConcept6Bullet3": "Löschung: Löschen Sie widersprüchliche oder veraltete Regeln sofort, um die logische Struktur rein zu halten.",
    "guideConcept6FormulaTitle": "Symbolische Regelsyntax:",
    "guideConcept6FormulaAntecedents": "Antezedenzien: ?x, traegt_bei_zu, ?y UND ?y, unterliegt, investitionsgesetz",
    "guideConcept6FormulaConsequent": "Konsequent: ?x, immun_gegen, direkte_beschlagnahme",
    "guideConcept7Title": "🧩 7. Kognitives Prompt-Engineering-Framework",
    "guideConcept7Desc": "Verwenden Sie diese Standard-Systempromptvorlage, um jedes logische Rätsel oder jede Textabfrage in eine formatierte JSON-Prozedurkette zu strukturieren, die das LEGEND-System ausführen und lösen kann.",
