    "metaVagueConceptsTitle": "⚖️ Conceitos vagos (Baixo grau ou baixa confiança)",
    "metaNoVagueConcepts": "Todos os conceitos têm contexto relacional suficiente e métricas de confiança equilibradas.",
    "metaVagueLinks": "links",
    "metaVagueConfidence": "confiança",
    "metaWaitingForAssessment": "Clique em 'Atualizar diagnóstico' para escanear o gráfico.",
    "cognitivePrompt": "Você é um arquiteto cognitivo neuro-simbólico. Sua tarefa é receber qualquer quebra-cabeça lógico, dilema ou problema de raciocínio, e então desconstruí-lo para gerar um \"Procedimento cognitivo sequencial\" que represente o algoritmo de raciocínio humano e simbólico necessário para resolver esse problema com absoluta precisão e de maneira organizada.\n\nVocê deve analisar o quebra-cabeça e formular etapas lógicas, onde cada etapa leva de forma lógica e progressiva à seguinte, evitando generalidades e focando em regras de dedução, raciocínio reverso e filtragem eliminatória.\n\nFormate a saída final estritamente como um JSON limpo, correspondendo exatamente à seguinte estrutura, sem qualquer introdução ou formatação markdown adicional:\n\n{\n  \"procedure_name\": \"nome_do_procedimento_cognitivo\",\n  \"steps\": [\n    \"Primeira etapa: ...\",\n    \"Segunda etapa: ...\",\n    \"Terceira etapa: ...\"\n  ]\n}\n\nAviso: Retorne APENAS o código JSON, sem qualquer texto introdutório, explicação ou tags markdown.",
    "guideMainTitle": "Guia Interativo Completo da IA Neuro-Simbólica LEGEND",
    "guideMainDesc": "Bem-vindo ao Guia de Conhecimento LEGEND. Este documento detalha as teorias, modelos matemáticos e estruturas de implementação que alimentam a integração conexionista-simbólica.",
    "guideConcept1Title": "🧠 1. IA Neuro-Simbólica Híbrida",
    "guideConcept1Desc": "Grandes Modelos de Linguagem (LLMs) são excelentes na análise de linguagem natural, mas sofrem de alucinações. O LEGEND resolve isso acoplando arquiteturas conexionistas com um banco de dados de ontologia SQLite simbólico estrito. O LLM extrai tuplas semânticas de entradas humanas, enquanto o motor rígido avalia restrições lógicas e resolve consultas com 0% de alucinações.",
    "guideConcept1Diagram1": "Cérebro Conexionista (Analisador LLM)",
    "guideConcept1Diagram2": "(Extração de Conceitos)",
    "guideConcept1Diagram3": "Memória Simbólica Estrita (Gráfico SQLite)",
    "guideConcept2Title": "⚖️ 2. Redes Lógicas Probabilísticas (PLN)",
    "guideConcept2Desc": "Ao contrário da lógica booleana clássica (verdadeiro/fals), o LEGEND quantifica os fatos usando um parâmetro de confiança contínuo entre 0.00 e 1.00. Os valores de confiança propagam-se através do gráfico semântico via cadeias transitivas, permitindo que a rede emule o raciocínio humano difuso e detecte paradoxos cognitivos.",
    "guideConcept2Example1": "Fato: (Ahmad ➔ amigo ➔ Mohammad) | Confiança = 0.95",
    "guideConcept2Example2": "Fato: (Mohammad ➔ amigo ➔ Khalid) | Confiança = 0.90",
    "guideConcept2Example3": "Inferência PLN: (Ahmad ➔ amigo ➔ Khalid) | Confiança Inferida = 0.85",
    "guideConcept3Title": "💤 3. Curiosidade & Ciclo de Sono Cognitivo",
    "guideConcept3Desc": "Para combater a entropia semântica cumulativa, o sistema executa periodicamente um Ciclo de Sono Cognitivo. O motor classifica os nós de conceito usando a centralidade do autovetor do gráfico, poda links fracos com confiança < 0.40 e implanta o Motor de Curiosidade para formular perguntas investigativas sobre entidades subdefinidas.",
    "guideConcept3Step1": "1. Classificar nós usando a Centralidade do Autovetor do Gráfico",
    "guideConcept3Step2": "2. Podar fatos com confiança < 0.40",
    "guideConcept3Step3": "3. Agregar entidades vagas para formular consultas de curiosidade",
    "guideConcept4Title": "🪐 4. Sandbox Contrafactual Hipotética",
    "guideConcept4Desc": "A Sandbox Contrafactual fornece uma ramificação isolada do seu banco de dados. Você pode testar afirmações hipotéticas, regras conflitantes ou gatilhos lógicos na memória. Se os efeitos em cascata hipotéticos forem úteis, clicar em 'Confirmar' integra essas alterações de volta ao banco de dados estável principal.",
    "guideConcept4Step1": "- Sandbox: Inferência de raciocínio hipotético isolada em RAM.",
    "guideConcept4Step2": "- Confirmar: Gravar modificações permanentemente no banco de dados SQLite estável.",
    "guideConcept4Step3": "- Descartar: Redefinir a sandbox hipotética sem deixar vestígios.",
    "guideConcept5Title": "⚖️ 5. Motor de Lógica Difusa-Modal Árabe",
    "guideConcept5Desc": "O analisador de lógica difusa árabe mapeia qualificadores de linguagem natural (ex: definitivamente, provavelmente, raramente, talvez) diretamente para métricas de probabilidade contínuas, permitindo que o motor autocalibre os valores de confiança sem entrada numérica manual (ex: definitivamente produz 0.99, raramente produz 0.35).",
    "guideConcept6Title": "🧩 6. Governança de Regras Lógicas Personalizadas",
    "guideConcept6Desc": "O LEGEND capacita os usuários a supervisionar as regras lógicas diretamente. Um painel de controle dedicado permite a criação manual, revisão e exclusão de regras lógicas personalizadas:",
    "guideConcept6Bullet1": "Criação manual: Insira o nome da regra, certeza, antecedentes e consequências usando variáveis simbólicas como ?x e ?y.",
    "guideConcept6Bullet2": "Extração por indução: Acione o sistema para varrer triplos do banco de dados ativo e autoinduzir regras lógicas latentes.",
    "guideConcept6Bullet3": "Exclusão: Exclua instantaneamente regras contraditórias ou obsoletas para manter a estrutura lógica pura.",
    "guideConcept6FormulaTitle": "Sintaxe de Regra Simbólica:",
    "guideConcept6FormulaAntecedents": "Antecedentes: ?x, contribui_para, ?y E ?y, sujeito_a, lei_investimento",
    "guideConcept6FormulaConsequent": "Consequente: ?x, imune_contra, apreensao_direta",
    "guideConcept7Title": "🧩 7. Estrutura de Engenharia de Prompt Cognitivo",
    "guideConcept7Desc": "Use este modelo de prompt de sistema padrão para estruturar qualquer quebra-cabeça lógico ou consulta de texto em uma cadeia procedural JSON formatada que o sistema LEGEND possa executar e resolver.",
