    "metaWaitingForAssessment": "「診断を更新」をクリックして、認知ネットワークグラフをスキャンします。",
    "cognitivePrompt": "あなたは神経符号化認知アーキテクトです。あなたのタスクは、あらゆる論理パズル、ジレンマ、または推論問題を受け取り、それを解体して、絶対的な精度で整理された方法でこの問題を解決するために必要な人間および記号推論アルゴリズムを表す「逐次認知手順」を生成することです。\n\nパズルを分析し、各ステップが論理的かつ段階的に次のステップにつながる論理ステップを策定する必要があります。その際、一般論を避け、演繹ルール、逆方向推論、排除フィルタリングに焦点を当てる必要があります。\n\n最終的な出力を、追加の導入テキストや markdown 形式なしで、次の構造に正確に一致するクリーンな JSON として厳密にフォーマットします。\n\n{\n  \"procedure_name\": \"手続き名\",\n  \"steps\": [\n    \"最初のステップ: ...\",\n    \"2番目のステップ: ...\",\n    \"3番目のステップ: ...\"\n  ]\n}\n\n警告：JSONコードのみを返してください。紹介文、説明、または markdown タグは一切含めないでください。",
    "guideMainTitle": "LEGEND 記号・接続ハイブリッドAI 総合インタラクティブガイド",
    "guideMainDesc": "LEGENDナレッジガイドへようこそ。このドキュメントでは、接続主義と記号主義の統合を支える理論、数学的モデル、および実装構造について詳しく説明します。",
    "guideConcept1Title": "🧠 1. ハイブリッド神経記号AI",
    "guideConcept1Desc": "大規模言語モデル（LLM）は自然言語の解析に優れていますが、ハルシネーション（幻覚）に悩まされます。LEGENDは、接続主義アーキテクチャと厳格な記号論的SQLiteオントロジーデータベースを結合することでこれを解決します。LLMが人間からの入力からセマンティックタプルを抽出し、厳格なエンジンが論理的制約を評価してハルシネーション0%でクエリを解決します。",
    "guideConcept1Diagram1": "接続マインド (LLMパーサー)",
    "guideConcept1Diagram2": "(概念抽出)",
    "guideConcept1Diagram3": "厳格な記号メモリ (SQLiteグラフ)",
    "guideConcept2Title": "⚖️ 2. 確率的論理ネットワーク (PLN)",
    "guideConcept2Desc": "従来の二値論理（真/偽）とは異なり、LEGENDは0.00から1.00の間の連続的な信頼度パラメータを使用して事実を定量化します。信頼度は推移的なチェーンを介して意味グラフ全体に伝播し、ネットワークが曖昧な人間の推論をエミュレートし、認知の矛盾を検出できるようにします。",
    "guideConcept2Example1": "事実: (Ahmad ➔ 友人 ➔ Mohammad) | 信頼度 = 0.95",
    "guideConcept2Example2": "事実: (Mohammad ➔ 友人 ➔ Khalid) | 信頼度 = 0.90",
    "guideConcept2Example3": "PLN推論: (Ahmad ➔ 友人 ➔ Khalid) | 推論信頼度 = 0.85",
    "guideConcept3Title": "💤 3. 好奇心と認知睡眠サイクル",
    "guideConcept3Desc": "累積的なセマンティックエントロピーに対抗するため、システムは定期的に認知睡眠サイクルを実行します。エンジンはグラフの固有ベクトル中心性を使用して概念ノードをランク付けし、信頼度 < 0.40の弱いリンクを整理し、定義が不十分なエンティティについて調査的な質問を策定するために好奇心エンジンを展開します。",
    "guideConcept3Step1": "1. グラフ固有ベクトル中心性を使用してノードをランク付けする",
    "guideConcept3Step2": "2. 信頼度 < 0.40の事実を整理する",
    "guideConcept3Step3": "3. 好奇心クエリを策定するために曖昧なエンティティを集約する",
    "guideConcept4Title": "🪐 4. 仮説的反事実サンドボックス",
    "guideConcept4Desc": "反事実サンドボックスは、データベースの隔離されたフォークを提供します。メモリ内で仮説的な主張、対立するルール、または論理的トリガーをテストできます。仮説的なカスケード効果が有用な場合、「コミット」をクリックすると、これらの変更がプライマリの安定したデータベースに統合されます。",
    "guideConcept4Step1": "- サンドボックス: RAM内に隔離された仮説的推論推論。",
    "guideConcept4Step2": "- コミット: 安定した SQLite データベースに変更を永久に書き込む。",
    "guideConcept4Step3": "- ロールバック: 痕跡を残さずに仮説サンドボックスをリセットする。",
    "guideConcept5Title": "⚖️ 5. アラビア語曖昧・様相論理エンジン",
    "guideConcept5Desc": "アラビア語曖昧論理パーサーは、自然言語の修飾子（例：確実に、おそらく、めったにない、もしかすると）を連続的な確率メトリックに直接マッピングし、手動の数値入力なしでエンジンが信頼度値を自動調整できるようにします（例：「確実に」は0.99、「めったにない」は0.35を出力）。",
    "guideConcept6Title": "🧩 6. カスタム論理ルールの管理",
    "guideConcept6Desc": "LEGENDは、ユーザーが論理ルールを直接監視できるようにします。専用のコントロールダッシュボードにより、カスタム論理ルールの手動作成、レビュー、および削除が可能になります。",
    "guideConcept6Bullet1": "手動作成: ?x や ?y などの記号変数を使用して、ルール名、確実性、前提条件、および結果を入力します。",
    "guideConcept6Bullet2": "帰納抽出: システムをトリガーしてアクティブなデータベースの三つ組をスキャンし、潜在的な論理ルールを自動帰納します。",
    "guideConcept6Bullet3": "削除: 論理構造を純粋に保つために、矛盾するルールや古いルールを即座に削除します。",
    "guideConcept6FormulaTitle": "記号ルールの構文:",
    "guideConcept6FormulaAntecedents": "前提条件: ?x, に貢献する, ?y AND ?y, 対象となる, 投資法",
    "guideConcept6FormulaConsequent": "結果: ?x, に対する免責, 直接差押え",
    "guideConcept7Title": "🧩 7. 認知プロンプトエンジニアリングフレームワーク",
    "guideConcept7Desc": "この標準システムプロンプトテンプレートを使用して、論理パズルやテキストクエリを、LEGENDシステムが実行して解決できるフォーマットされたJSON手続きチェーンに構造化します。",
