    "metaEngineDesc": "개념 그래프를 스캔하여 논리적 이상, 순환 루프 및 격리된 하위 그래프를 식별합니다.",
    "metaRefreshBtn": "진단 새로고침",
    "metaHealthIndex": "인지 무결성 지수",
    "metaHealthyMsg": "🧠 균형 잡히고 매우 일관된 정신",
    "metaUnhealthyMsg": "⚠️ 경미한 의미적 발산이 감지되었습니다",
    "metaInfiniteLoopsTitle": "🔄 무한 추론 루프",
    "metaNoLoops": "완벽합니다! 순환 종속성 또는 무한 루프가 감지되지 않았습니다.",
    "metaIsolatedTitle": "🏝️ 격리된 개념 구성 요소",
    "metaNoIsolated": "훌륭합니다! 모든 개념이 네트워크 그래프에 아름답게 통합되었습니다.",
    "metaVagueConceptsTitle": "⚖️ 모호한 개념 (차수 또는 신뢰도가 낮음)",
    "metaNoVagueConcepts": "모든 개념은 충분한 관계형 맥락과 균형 잡힌 신뢰도 지표를 가지고 있습니다.",
    "metaVagueLinks": "링크",
    "metaVagueConfidence": "신뢰도",
    "metaWaitingForAssessment": "인지 네트워크 그래프를 스캔하려면 '진단 새로고침'을 클릭하십시오.",
    "cognitivePrompt": "당신은 신경-기호 인지 아키텍트입니다. 당신의 임무는 논리 퍼즐, 딜레마 또는 추론 문제를 받아들인 다음 이를 해체하여이 문제를 절대적인 정확성과 조직적인 방식으로 해결하는 데 필요한 인간 및 기호 추론 알고리즘을 나타내는 \"순차적 인지 절차\"를 생성하는 것입니다.\n\n퍼즐을 분석하고 각 단계가 논리적이고 점진적으로 다음 단계로 이어지는 논리적 단계를 수립해야하며 일반적인 내용을 피하고 연역 규칙, 역방향 추론 및 배제 필터링에 집중해야합니다.\n\n추가 소개 텍스트 나 markdown 서식없이 최종 출력을 다음 구조와 정확히 일치하는 깨끗한 JSON으로 서식을 지정하십시오.\n\n{\n  \"procedure_name\": \"절차명\",\n  \"steps\": [\n    \"첫 번째 단계: ...\",\n    \"두 번째 단계: ...\",\n    \"세 번째 단계: ...\"\n  ]\n}\n\n경고: JSON 코드만 반환하고 소개 텍스트, 설명 또는 markdown 태그를 포함하지 마십시오.",
    "guideMainTitle": "LEGEND 신경-기호 AI 종합 대화형 가이드",
    "guideMainDesc": "LEGEND 지식 가이드에 오신 것을 환영합니다. 이 문서는 연결주의와 기호주의의 통합을 지원하는 이론, 수학적 모델 및 구현 구조를 자세히 설명합니다.",
    "guideConcept1Title": "🧠 1. 하이브리드 신경-기호 AI",
    "guideConcept1Desc": "대규모 언어 모델(LLM)은 자연어 분석에 뛰어나지만 환각 현상으로 어려움을 겪습니다. LEGEND는 연결주의 아키텍처와 엄격한 기호 기호 SQLite 온톨로지 데이터베이스를 결합하여 이 문제를 해결합니다. LLM은 인간의 입력에서 의미론적 튜플을 추출하고, 엄격한 엔진은 논리적 제약 조건을 평가하여 환각 0%로 쿼리를 해결합니다.",
    "guideConcept1Diagram1": "연결주의 인지 뇌 (LLM 파서)",
    "guideConcept1Diagram2": "(개념 추출)",
    "guideConcept1Diagram3": "엄격한 기호 메모리 (SQLite 그래프)",
    "guideConcept2Title": "⚖️ 2. 확률적 논리 네트워크 (PLN)",
    "guideConcept2Desc": "기존의 이진 논리(참/거짓)와 달리 LEGEND는 0.00에서 1.00 사이의 연속적인 신뢰도 매개변수를 사용하여 사실을 정량화합니다. 신뢰도 값은 전이적 체인을 통해 의미론적 그래프 전체로 전파되어 네트워크가 모호한 인간의 추론을 에뮬레이트하고 인지적 모순을 감지할 수 있도록 합니다.",
    "guideConcept2Example1": "사실: (Ahmad ➔ 친구 ➔ Mohammad) | 신뢰도 = 0.95",
    "guideConcept2Example2": "사실: (Mohammad ➔ 친구 ➔ Khalid) | 신뢰도 = 0.90",
    "guideConcept2Example3": "PLN 추론: (Ahmad ➔ 친구 ➔ Khalid) | 추론된 신뢰도 = 0.85",
    "guideConcept3Title": "💤 3. 호기심 & 인지 수면 주기",
    "guideConcept3Desc": "누적되는 의미론적 엔트로피에 대응하기 위해 시스템은 정기적으로 인지 수면 주기를 실행합니다. 엔진은 그래프 고유벡터 중심성을 사용하여 개념 노드의 순위를 매기고, 신뢰도 < 0.40인 약한 링크를 정리하며, 정의가 부족한 엔티티에 대해 조사 질문을 작성하기 위해 호기심 엔진을 배포합니다.",
    "guideConcept3Step1": "1. 그래프 고유벡터 중심성을 사용하여 노드 순위 매기기",
    "guideConcept3Step2": "2. 신뢰도 < 0.40인 사실 정리하기",
    "guideConcept3Step3": "3. 호기심 쿼리를 작성하기 위해 모호한 엔티티 수집하기",
    "guideConcept4Title": "🪐 4. 가설적 반사실 샌드박스",
    "guideConcept4Desc": "반사실 샌드박스는 데이터베이스의 격리된 포크를 제공합니다. 메모리에서 가설적 주장, 충돌하는 규칙 또는 논리적 트리거를 테스트할 수 있습니다. 가설적 연쇄 효과가 유용한 경우 '반영'을 클릭하면 이러한 변경 사항이 기본 안정 데이터베이스에 통합됩니다.",
    "guideConcept4Step1": "- 샌드박스: RAM에 격리된 가설적 추론 추론.",
    "guideConcept4Step2": "- 반영: 변경 사항을 안정적인 SQLite 데이터베이스에 영구적으로 기록.",
    "guideConcept4Step3": "- 되돌리기: 가설 샌드박스를 흔적 없이 초기화.",
    "guideConcept5Title": "⚖️ 5. 아랍어 퍼지-양상 논리 엔진",
    "guideConcept5Desc": "아랍어 퍼지 논리 파서는 자연어 한정사(예: 확실히, 아마도, 드물게, 어쩌면)를 연속적인 확률 지표에 직접 매핑하여 수동 숫자 입력 없이 엔진이 신뢰도 값을 자동 조정할 수 있도록 합니다(예: '확실히'는 0.99, '드물게'는 0.35 산출).",
    "guideConcept6Title": "🧩 6. 사용자 정의 논리 규칙 관리",
    "guideConcept6Desc": "LEGEND는 사용자가 논리 규칙을 직접 모니터링할 수 있도록 지원합니다. 전용 제어 대시보드를 통해 사용자 정의 논리 규칙을 수동으로 생성, 검토 및 삭제할 수 있습니다.",
    "guideConcept6Bullet1": "수동 생성: ?x 및 ?y 같은 기호 변수를 사용하여 규칙 이름, 확실성, 전제 조건 및 결과를 입력합니다.",
    "guideConcept6Bullet2": "귀납 추출: 시스템을 트리거하여 활성 데이터베이스 트리플을 스캔하고 잠재적인 논리 규칙을 자동 귀납합니다.",
    "guideConcept6Bullet3": "삭제: 논리 구조를 순수하게 유지하기 위해 모순되거나 오래된 규칙을 즉시 삭제합니다.",
    "guideConcept6FormulaTitle": "기호 규칙 구문:",
    "guideConcept6FormulaAntecedents": "전제 조건: ?x, 에_기여함, ?y 그리고 ?y, 대상이_됨, 투자법",
    "guideConcept6FormulaConsequent": "결과: ?x, 에_대한_면제, 직접_압류",
    "guideConcept7Title": "🧩 7. 인지 프롬프트 엔지니어링 프레임워크",
    "guideConcept7Desc": "이 표준 시스템 프롬프트 템플릿을 사용하여 모든 논리 퍼즐 또는 텍스트 쿼리를 LEGEND 시스템이 실행하고 해결할 수 있는 형식화된 JSON 절차 체인으로 구성하십시오.",
